// ─── Fallback genérico (SVG cor-sólida) ─────────────────────────────────────

const px = (color: string) =>
  `data:image/svg+xml,%3Csvg%20xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width='20'%20height='13'%3E%3Crect%20fill='${color}'%20width='20'%20height='13'%2F%3E%3C%2Fsvg%3E`;

/** Cinza neutro — fallback para imagens sem blur hash real */
export const BLUR_GREY   = px("%23e5e7eb");

